{"meetingId": "293", "tickets": [
{"title": "Update recurring payment instructions", "text": "Increase Daria Copperwisp's recurring net monthly IRA distribution from $4,500 to $6,200, paid to her existing Teacup Comet Bank checking account at Velvet Acorn Custody. Implement the revised distribution amount as the new standing instruction.", "priority": null, "dueDate": "2025-07-11", "assigneeId": null, "templateId": "3a4e7ad2-bf7e-54d7-9b37-c81d19056200", "subTasks": [], "evidence": "Daria asked for the net monthly IRA distribution sent to her existing Teacup Comet Bank checking account to increase from $4,500 to $6,200. The agreed follow-up is to implement the increase by 2025-07-11."},
{"title": "Review retirement income bridge plan", "text": "Complete a retirement income bridge review for Daria and Owen Copperwisp reflecting Daria's 2025-01-31 retirement from Moonbadger Design Works and Owen's consulting income from Paper Otter Analytics averaging $3,800 gross per month. Determine whether monthly withdrawals should come from Daria's rollover IRA, the joint taxable account at Velvet Acorn Custody, or cash reserves at Teacup Comet Bank.", "priority": null, "dueDate": "2025-07-25", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The agreed follow-up is to complete that review by 2025-07-25."},
{"title": "Process one-time taxable account distribution", "text": "Process an $18,000 one-time distribution from Daria and Owen Copperwisp's joint taxable account at Velvet Acorn Custody for the family tuition contribution for granddaughter Nora Copperwisp at Cloudberry Kite Academy. The funds must clear before Nora's school orientation.", "priority": null, "dueDate": "2025-07-18", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "Daria asked for an $18,000 one-time distribution from the joint taxable account for the family tuition contribution that must clear before Nora's school orientation. The agreed follow-up is to process the distribution by 2025-07-18."},
{"title": "Obtain health insurance premium notice", "text": "Obtain Daria Copperwisp's current marketplace health insurance premium notice to verify the monthly spending estimate of about $9,700 per month used for withdrawal planning. Daria did not have the notice available during the meeting.", "priority": null, "dueDate": "2025-07-09", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the notice is needed to verify the monthly spending estimate used for withdrawal planning. The agreed follow-up is to obtain the documentation by 2025-07-09."},
{"title": "Check federal withholding instruction", "text": "Check Daria Copperwisp's federal withholding instruction on her recurring IRA distributions at Velvet Acorn Custody, which currently shows 10% federal withholding, before entering the revised $6,200 net payment. Daria recalled electing a higher rate than the custodian record shows.", "priority": null, "dueDate": "2025-07-15", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the withholding instruction needs to be checked before the revised payment is entered. The agreed follow-up is to check the withholding instruction by 2025-07-15."},
{"title": "Review distribution processing timetable", "text": "Review the IRA distribution processing timetable at Velvet Acorn Custody after the most recent payment to Daria Copperwisp posted later than the normal household bill cycle, requiring her to move cash from savings to avoid an overdraft at Teacup Comet Bank.", "priority": null, "dueDate": "2025-07-10", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the most recent IRA payment posted later than the normal household bill cycle, and Daria reported moving cash from savings to avoid an overdraft. The agreed follow-up is to review the distribution processing timetable by 2025-07-10."},
{"title": "Prepare funding plan for scheduled withdrawals", "text": "Prepare a funding plan for scheduled withdrawals from Daria and Owen Copperwisp's joint taxable account at Velvet Acorn Custody that avoids unnecessary realized gains, noting the $18,600 capital loss carryforward from their 2024 tax return. Mira's pre-call review found the taxable account cash and short-term bond sleeve above the household reserve target.", "priority": null, "dueDate": "2025-07-22", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the portfolio needs a funding plan for scheduled withdrawals that avoids unnecessary realized gains. The agreed follow-up is to prepare that funding plan by 2025-07-22."}
]}
